package com.example.starter.model;

/**
 * 调度单状态机：DISPATCHED 在途 → GENERATING 发电中；超时未确认升级 GENERATION_ABNORMAL；
 * 市电恢复转 RELEASED；结案 CLOSED 为终态。
 */
public enum OrderStatus {
    /** 已派单，油机在途，等待发电确认。 */
    DISPATCHED,
    /** 油机已到位启动并回传发电确认。 */
    GENERATING,
    /** 发电确认超时（30 分钟，恰满判超时），已释放原油机，允许改派。 */
    GENERATION_ABNORMAL,
    /** 市电恢复，调度解除，油机已释放。 */
    RELEASED,
    /** 结案，终态，不再接受任何状态变更。 */
    CLOSED
}

package com.example.starter.model;

/**
 * 停电事件状态：ACTIVE 停电中；RESOLVED 市电已恢复。
 */
public enum OutageStatus {
    /** 停电中，事件期内重复告警合并到本事件。 */
    ACTIVE,
    /** 市电已恢复。 */
    RESOLVED
}

package com.example.starter.model;

/**
 * 油机状态：IDLE 空闲可分配；ASSIGNED 已分配在服务某基站。
 */
public enum GeneratorStatus {
    /** 空闲，可被调度。 */
    IDLE,
    /** 已分配，正在服务某一基站。 */
    ASSIGNED
}

package com.example.starter.config;

import java.time.Clock;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 全局时钟配置：业务时间统一取自该 Clock（UTC），测试可替换为可控时钟。
 */
@Configuration
public class ClockConfig {

    /**
     * 生产默认使用 UTC 系统时钟。
     */
    @Bean
    public Clock clock() {
        return Clock.systemUTC();
    }
}

