package com.example.starter.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 基站档案。
 *
 * @param id                  主键
 * @param code                基站编码，全局唯一
 * @param loadKw              平均负载功率，单位千瓦
 * @param batteryCapacityKwh  电池组额定容量，单位千瓦时
 * @param createdAt           创建时间，UTC
 */
public record Station(long id, String code, BigDecimal loadKw, BigDecimal batteryCapacityKwh,
                      Instant createdAt) {
}

package com.example.starter.model;

import java.time.Instant;

/**
 * 油机档案。
 *
 * @param id        主键
 * @param code      油机编号，全局唯一
 * @param status    油机状态：IDLE 空闲 / ASSIGNED 已分配
 * @param createdAt 创建时间，UTC
 */
public record Generator(long id, String code, GeneratorStatus status, Instant createdAt) {
}

package com.example.starter.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 电池容量读数，按“基站＋抄表时刻”去重，乱序到达按抄表时刻归位。
 *
 * @param id               主键
 * @param stationCode      基站编码
 * @param readingTime      抄表时刻，UTC
 * @param remainingPercent 剩余容量百分比，0-100
 * @param requestId        上报请求幂等键
 * @param createdAt        入库时间，UTC
 */
public record BatteryReading(long id, String stationCode, Instant readingTime,
                             BigDecimal remainingPercent, String requestId, Instant createdAt) {
}

package com.example.starter.model;

import java.time.Instant;

/**
 * 基站停电事件；同一事件期内重复告警合并为一个事件。
 *
 * @param id              主键
 * @param stationCode     基站编码
 * @param outageStartTime 停电起始时刻，UTC
 * @param status          事件状态：ACTIVE 停电中 / RESOLVED 已恢复
 * @param resolvedAt      市电恢复时刻，UTC；未恢复为 null
 * @param createdAt       创建时间，UTC
 */
public record OutageEvent(long id, String stationCode, Instant outageStartTime, OutageStatus status,
                          Instant resolvedAt, Instant createdAt) {
}

package com.example.starter.model;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 油机调度单。
 *
 * @param id            主键
 * @param requestId     调度请求幂等键
 * @param stationCode   基站编码
 * @param generatorCode 当前服务油机编号；发电异常待改派时为 null
 * @param status        调度单状态，见 {@link OrderStatus}
 * @param supportHours  派单时估算的电池可支撑时长，单位小时
 * @param deadlineAt    预计到达时限，UTC
 * @param assignedAt    当前油机分配时刻，UTC；未分配为 null
 * @param confirmedAt   发电确认时刻，UTC；未确认为 null
 * @param closedAt      结案时刻，UTC；未结案为 null
 * @param createdAt     创建时间，UTC
 * @param updatedAt     最后更新时间，UTC
 */
public record DispatchOrder(long id, String requestId, String stationCode, String generatorCode,
                            OrderStatus status, BigDecimal supportHours, Instant deadlineAt,
                            Instant assignedAt, Instant confirmedAt, Instant closedAt,
                            Instant createdAt, Instant updatedAt) {

    /**
     * 判断调度单是否未完成（在途、发电中或发电异常待改派）。
     */
    public boolean unfinished() {
        return status == OrderStatus.DISPATCHED
                || status == OrderStatus.GENERATING
                || status == OrderStatus.GENERATION_ABNORMAL;
    }
}

package com.example.starter.model;

import java.time.Instant;

/**
 * 幂等记录：同键同参返回首次结果，同键异参拒绝（409）。
 *
 * @param requestId    幂等键
 * @param apiName      接口名称
 * @param fingerprint  请求指纹，覆盖 requestId 与全部业务字段
 * @param responseBody 首次成功响应快照，JSON
 * @param createdAt    创建时间，UTC
 */
public record IdempotencyRecord(String requestId, String apiName, String fingerprint,
                                String responseBody, Instant createdAt) {
}

