@SpringBootTest
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
public abstract class BaseIntegrationTest {

    protected static final Instant T0 = Instant.parse("2026-09-25T08:00:00Z");

    @Autowired protected JdbcTemplate jdbcTemplate;
    @Autowired protected StationService stationService;
    @Autowired protected AlarmService alarmService;
    @Autowired protected DispatchService dispatchService;
    @Autowired protected StationRepository stationRepository;
    @Autowired protected GeneratorRepository generatorRepository;
    @Autowired protected DispatchOrderRepository orderRepository;
    @Autowired protected OrderEventRepository eventRepository;

    @MockitoBean protected Clock clock;

    protected Instant now;

    @BeforeEach
    void resetState() {
        now = T0;
        Mockito.lenient().when(clock.instant()).thenAnswer(inv -> now);
        Mockito.lenient().when(clock.getZone()).thenReturn(ZoneOffset.UTC);
        jdbcTemplate.update("DELETE FROM order_event");
        jdbcTemplate.update("DELETE FROM dispatch_order");
        jdbcTemplate.update("DELETE FROM outage_event");
        jdbcTemplate.update("DELETE FROM battery_reading");
        jdbcTemplate.update("DELETE FROM idempotency_record");
        jdbcTemplate.update("DELETE FROM generator");
        jdbcTemplate.update("DELETE FROM station");
